function validate([nums1, nums2]) {
  if (nums1.length < 1 || nums1.length > 3000) return 'nums1 needs 1 to 3000 values.';
  if (nums2.length !== nums1.length) return 'nums1 and nums2 must have the same length.';
  if (nums1.some((v) => v < 1 || v > 1e9) || nums2.some((v) => v < 1 || v > 1e9)) return 'Every value is between 1 and 10^9.';
  return null;
}

