function maximumMatchingIndices(nums1, nums2) {
  const n = nums1.length;
  let best = 0;
  for (let shift = 0; shift < n; shift++) {
    let matches = 0;
    for (let i = 0; i < n; i++) {
      if (nums1[(i - shift + n) % n] === nums2[i]) {
        matches++;
      }
    }
    best = Math.max(best, matches);
  }
  return best;
}

