function maximumMatchingIndices(nums1, nums2) {
  // Physically perform one right shift at a time and count the matches of every arrangement.
  let current = nums1.slice();
  let best = 0;
  for (let step = 0; step < nums1.length; step++) {
    best = Math.max(best, current.filter((value, i) => value === nums2[i]).length);
    current = [current[current.length - 1], ...current.slice(0, -1)];
  }
  return best;
}

