function generate(rand, size) {
  const large = size === 'large';
  const pick = (k) => Math.floor(rand() * k);
  const n = large ? 1500 + pick(501) : 1 + pick(8);
  const rotated = rand() < (large ? 0.6 : 0.5);
  // Independent random arrays only match often with few distinct values; a rotated copy matches with any values.
  const choices = rotated ? [2, 10, 1000000000] : large ? [2, 3, 10] : [1, 2, 3, 4, 1000000000];
  const limit = choices[pick(choices.length)];
  const value = () => 1 + pick(limit);
  const nums1 = Array.from({ length: n }, value);
  if (!rotated) return [nums1, Array.from({ length: n }, value)];
  // nums2 is nums1 shifted right by some amount, with part of it overwritten.
  const shift = pick(n);
  const noise = rand();
  const nums2 = nums1.map((_, i) => (rand() < noise ? value() : nums1[(i - shift + n) % n]));
  return [nums1, nums2];
}
